def verify_isbn(isbn: str) -> str:
    # Remove non-digit characters except possibly 'X' as last character
    if len(isbn) < 1:
        return isbn

    # Calculate the checksum
    # ISBN format: x-xxx-xxxxx-x (10 digits, last can be X)
    # The checksum is calculated as: sum(i * digit[i]) for i from 1 to 10
    # The result should be divisible by 11

    digits = []
    for i, char in enumerate(isbn):
        if char == '-':
            continue
        elif char == 'X' or char == 'x':
            digit_val = 10
        elif char.isdigit():
            digit_val = int(char)
        else:
            continue
        digits.append(digit_val)

    if len(digits) != 10:
        # Try to handle different formats
        # Extract only valid characters
        clean_isbn = ''.join([c for c in isbn if c.isdigit() or c in 'Xx'])
        digits = []
        for c in clean_isbn:
            if c in 'Xx':
                digits.append(10)
            elif c.isdigit():
                digits.append(int(c))
        if len(digits) != 10:
            return isbn

    # Calculate checksum
    checksum = 0
    for i in range(10):
        checksum += (i + 1) * digits[i]

    if checksum % 11 == 0:
        return "Right"
    else:
        # Need to find the correct last digit
        # Let's recalculate with last digit as variable
        # checksum = sum_{i=0}^{8} (i+1)*digits[i] + 10*x
        # We need (sum_{i=0}^{8} (i+1)*digits[i] + 10*x) % 11 == 0
        prefix_sum = 0
        for i in range(9):
            prefix_sum += (i + 1) * digits[i]

        # Find x such that (prefix_sum + 10*x) % 11 == 0
        found = False
        corrected_last = None
        for x in range(11):
            if (prefix_sum + 10 * x) % 11 == 0:
                corrected_last = x
                found = True
                break

        if not found:
            return isbn

        # Format the corrected ISBN
        # The last digit should be 0-9, or 'X' if 10
        last_char = 'X' if corrected_last == 10 else str(corrected_last)

        # Reconstruct the ISBN with the same format
        # Count the dashes and their positions
        result_chars = []
        digit_idx = 0
        for char in isbn:
            if char == '-':
                result_chars.append('-')
            else:
                if digit_idx == 9:
                    result_chars.append(last_char)
                else:
                    result_chars.append(str(digits[digit_idx]))
                digit_idx += 1

        return ''.join(result_chars)
