def max_happiness(n: int, m: int, items: list) -> int:
    # dp[i] = max importance with budget i
    dp = [0] * (n + 1)

    for cost, value in items:
        for budget in range(n, cost - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - cost] + value)

    return dp[n]
