def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    where each part is at least x and order of parts does not matter.
    """
    if k <= 0:
        return 1 if n == 0 else 0
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0

    # Recursive helper function
    def helper(n, k, min_val):
        if k == 0:
            return 1 if n == 0 else 0
        if k == 1:
            return 1 if n >= min_val else 0
        if n < k * min_val:
            return 0

        count = 0
        for i in range(min_val, n // k + 1):
            # i is the smallest part, so remaining parts must be at least i
            count += helper(n - i, k - 1, i)
        return count

    return helper(n, k, x)
