        root_index = inorder_list.index(root)

        left_inorder = inorder_list[:root_index]
        right_inorder = inorder_list[root_index + 1:]

        left_size = len(left_inorder)

        left_postorder = postorder_list[:left_size]
        right_postorder = postorder_list[left_size:-1]

        return root + build(left_inorder, left_postorder) + build(right_inorder, right_postorder)

