        current = queue.popleft()
        # Try all transformations on each digit
        for i in range(len(current)):
            digit = current[i]
            if digit in rule_map:
                for new_digit in rule_map[digit]:
                    if new_digit != digit:
                        new_number = current[:i] + str(new_digit) + current[i+1:]
                        if new_number not in visited:
