        is_liar = person in liar_count
        for stmt in stmts:
            # Skip statements about days of the week
            if stmt.upper() in days_of_week:
                continue

            # Determine the logical value of the statement under the current scenario
            # A statement is one of: "X is guilty", "X is not guilty", "I am guilty", "I am not guilty"
            # We can check by seeing if the statement mentions the scenario person or the current person.
            if "is guilty" in stmt:
                stmt_is_true = False
                if "not guilty" in stmt:
                    stmt_is_true = True
                # Check if the person referred to (by name or "I") is the criminal
                # Extract the subject of the statement
                if stmt.startswith("I "):
                    subject = person
                else:
                    # Format: "<NAME> is (not) guilty."
                    # Find the word before "is"
                    idx = stmt.find(" is ")
                    if idx == -1:
                        idx = stmt.find(" isn't ")
                    if idx != -1:
                        subject = stmt[:idx].strip()
                    else:
                        # Fallback, though format is assumed consistent
                        subject = ""

                if "not guilty" in stmt:
                    stmt_is_true = (subject != scenario)
                else:
                    stmt_is_true = (subject == scenario)
            elif stmt.startswith("I am guilty.") or stmt.startswith("I am not guilty."):
                if stmt.startswith("I am not guilty."):
                    stmt_is_true = (person != scenario)
                else:
