def jinjin_savings_plan(budgets: List[int]) -> int:
    money = 0
    saved = 0

    for month in range(12):
        money += 300
        if money < budgets[month]:
            return -(month + 1)
        money -= budgets[month]
        if money >= 100:
            save_amount = (money // 100) * 100
            saved += save_amount
            money -= save_amount

    total = money + int(saved * 1.2)
